import {presentationFor} from './presentation.mjs';
import {endpoint,net,colourCodes,layoutInfo} from './model.mjs';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
const text=(x,y,value,cls='',anchor='middle')=>`<text x="${x}" y="${y}" class="${cls}" text-anchor="${anchor}">${esc(value)}</text>`;
import {visuals} from './components.mjs';
export {visuals};
import {routeDiagram,routeSemantics} from './routing.mjs';
import {trueJunctions,crossingMarkers} from './diagram-semantics.mjs';
import {composePhysicalWiring,pickupProfile} from './physical.mjs';
const categoryColours={signal:'#303b43',ground:'#7a8187',tone:'#ad2929',switching:'#926f31'};
function isActive(c,kind,id,selection,filter,semantics){
 if(selection?.kind==='path'){const refs=new Set(selection.refs);if(kind==='wire'){const wire=c.connections.find(w=>w.id===id);return refs.has(wire.from)&&refs.has(wire.to);}return [...refs].some(ref=>ref.startsWith(id+'.'));}
 if(selection?.kind==='component'){if(kind==='component')return id===selection.id;if(kind==='wire'){const w=c.connections.find(w=>w.id===id);return w.from.startsWith(selection.id+'.')||w.to.startsWith(selection.id+'.');}}
 if(selection?.kind==='physical-wire'){const selected=c.connections.find(w=>w.id===selection.id);if(selected)return kind==='wire'?id===selected.id:[selected.from,selected.to].some(r=>r.startsWith(id+'.'));}
 if(selection?.kind==='wire'){const selected=c.connections.find(w=>w.id===selection.id);if(selected){const refs=net(c,selected.from);return kind==='wire'?refs.has(c.connections.find(w=>w.id===id).from):[...refs].some(r=>r.startsWith(id+'.'));}}
 if(selection?.kind==='stage'){return kind==='component'?selection.ids.includes(id):c.connections.some(w=>w.id===id&&(selection.ids.some(p=>w.from.startsWith(p+'.')||w.to.startsWith(p+'.'))));}
 if(filter!=='all'){
  const matches=w=>{const role=semantics.get(w.id).role;return role===filter||(filter==='switching'&&role==='switch')||(filter==='tone'&&role==='auxiliary');};
  if(kind==='wire')return matches(c.connections.find(w=>w.id===id));
  return c.connections.some(w=>matches(w)&&(w.from.startsWith(id+'.')||w.to.startsWith(id+'.')));
 }
 return true;
}
export function drawCircuit(c,{selection=null,filter='all',exporting=false,view='full',mode='trace'}={}){
 const policy=presentationFor(c,mode);mode=policy.mode;if(policy.build){selection=null;filter='all';}
 const artworkLabel=label=>{if(!policy.build)return label;if(/class="(blade-terminal-label|micro|sheet-caption)"/.test(label)||label.includes('C: COMMON'))return '';return label.replace('3 / CW','3').replace('2 / WIPER','2').replace('1 / CCW','1').replace('TIP / SIGNAL','TIP').replace('SLEEVE / GROUND','SLEEVE');};
 const routes=routeDiagram(c,{mode:policy.routing}),semantics=routeSemantics(c,{contacts:!policy.build}),physical=composePhysicalWiring(c);
 const wireColour=(w,a)=>w.conductor?pickupProfile(c,a.component.id).wires[w.conductor][0]:policy.build?(w.category==='ground'?'#7a8187':w.category==='tone'?'#675533':'#303b43'):categoryColours[w.category];
 const codes=colourCodes[c.state.colours];
 const meta=policy.build?`${layoutInfo[c.state.guitar].label} / ${c.state.wiring.toUpperCase()} / BUILD WIRING`:`${layoutInfo[c.state.guitar].label} / ${c.state.wiring.toUpperCase()} / SELECTOR ${c.state.position.toUpperCase()}`;
 const labelLayer=[];
 for(const part of c.components)if(!['capacitor','resistor','network'].includes(part.type))labelLayer.push(`<g transform="translate(${part.x} ${part.y})" class="${part.existing?'not-supplied':''} ${isActive(c,'component',part.id,selection,filter,semantics)?'':'muted'}">${text(['humbucker','singlecoil'].includes(part.type)?77:['blade','superswitch'].includes(part.type)?95:0,part.type==='pot'?8:-20,part.label,'part-title')}</g>`);
 const bodies=c.components.map(part=>`<g class="component ${part.existing?'not-supplied':'supplied'} ${isActive(c,'component',part.id,selection,filter,semantics)?'':'muted'}" transform="translate(${part.x} ${part.y})" data-component="${part.id}" ${exporting?'':`tabindex="0" role="button" aria-label="Inspect ${esc(part.label)}"`}><title>${esc(part.label+' / '+part.value)}</title>${visuals[part.type](part).replace(/<text[\s\S]*?<\/text>/g,label=>{label=artworkLabel(label);labelLayer.push(`<g transform="translate(${part.x} ${part.y})" class="${part.existing?'not-supplied':''} ${isActive(c,'component',part.id,selection,filter,semantics)?'':'muted'}">${label}</g>`);return '';})}</g>`).join('');
 const contactRefs=new Set(policy.showContacts?c.contacts.flat():[]);
 const selectedRefs=selection?.kind==='path'?new Set(selection.refs):new Set();
 const contacts=(policy.showContacts?c.contacts:[]).filter(([a])=>['blade','blade3','blade5','superswitch'].includes(endpoint(c,a).component.type)).map(([a,b])=>{const p=endpoint(c,a),q=endpoint(c,b),lane=p.y+(a.split('.')[1].startsWith('A')?32:-32),active=!selection||selectedRefs.has(a)||selectedRefs.has(b)||isActive(c,'component',p.component.id,selection,filter,semantics);return `<g class="selector-contact ${active?'':'muted'}" data-contact-from="${esc(a)}" data-contact-to="${esc(b)}" data-contact-state="closed"><title>${esc(a+' ↔ '+b+' closed')}</title><path class="closed-contact" data-route-role="switch" d="M${p.x} ${p.y}V${lane}H${q.x}V${q.y}"/></g>`;}).join('');
 const wires=c.connections.map(w=>{
  const a=endpoint(c,w.from),b=endpoint(c,w.to),points=routes.get(w.id),d=points.map((p,i)=>(i?'L':'M')+p.join(' ')).join(' '),active=isActive(c,'wire',w.id,selection,filter,semantics),colour=wireColour(w,a),semantic=semantics.get(w.id),intent=physical.conductors.get(w.id);
  return `<g class="wire ${(w.supplied===false||w.supplied===undefined&&(a.component.existing||b.component.existing))?'not-supplied':'supplied'} ${active?'':'muted'}" data-wire="${esc(w.id)}" data-physical-kind="${esc(intent.kind)}" data-conductor="${esc(intent.colour||'')}" data-series-colours="${esc(intent.seriesColours?.join(' + ')||'')}" data-route-role="${semantic.role}" data-route-net="${esc(semantic.net)}" data-view-state="${active?(selection?.kind==='physical-wire'?'selected':selection?'traced':'active'):'muted'}" ${exporting?'':`tabindex="0" role="button" aria-label="Trace ${esc(a.component.label+' '+a.terminal.label+' to '+b.component.label+' '+b.terminal.label)}"`}><title>${esc(w.from+' → '+w.to)}</title><path class="wire-clear" d="${d}"/><path class="wire-line ${w.conductor==='shield'?'bare-wire':''} role-${semantic.role}" stroke="${colour||categoryColours[w.category]}" d="${d}"/>${intent.kind==='local-series'?`<rect class="insulation" x="${points[1][0]-5}" y="${(points[1][1]+points[2][1])/2-9}" width="10" height="18" rx="3"/>`:''}${exporting?'':`<path class="wire-hit" d="${d}"/>`}</g>`;
 }).join('');
 const junctions=new Map(trueJunctions(c).map(j=>[j.ref,j]));
 const terminals=c.components.map(part=>`<g class="anchors ${part.existing?'not-supplied':''} ${isActive(c,'component',part.id,selection,filter,semantics)?'':'muted'}">${Object.entries(part.terminals).map(([key,t])=>{const x=part.x+t.x,y=part.y+t.y,ref=part.id+'.'+key,count=c.connections.filter(w=>w.from===ref||w.to===ref).length,junction=junctions.get(ref),solder=physical.solderPoints.get(ref);return `${count?`<ellipse class="solder-joint ${solder?'casing-solder':''}" cx="${x}" cy="${y}" rx="7" ry="6"${solder&&!exporting?` data-terminal="${esc(ref)}"`:""} ${solder?`data-solder-point="${esc(ref)}" data-solder-conductors="${esc(solder.conductors.join(' '))}" data-local-bonds="${esc(solder.localBonds.join(' '))}"`:''}/>`:''}<circle class="terminal ${count?'':'unused-terminal'} ${selectedRefs.has(ref)?'terminal-traced':''} ${contactRefs.has(ref)?'contact-engaged':''}" cx="${x}" cy="${y}" r="5" data-terminal="${esc(ref)}" ${exporting?'':`tabindex="0" role="button" aria-label="Inspect ${esc(part.label+' '+key+' / '+t.label)}"`}><title>${esc(part.label+' / '+t.label)}</title></circle>${junction&&!solder?`<circle class="junction" cx="${x}" cy="${y}" r="3.5" data-junction="${esc(ref)}" data-junction-wires="${esc(junction.wires.join(' '))}" pointer-events="none"/>`:''}`;}).join('')}</g>`).join('');
 const conductors=c.components.filter(p=>['humbucker','singlecoil','p90'].includes(p.type)).map(p=>`<g class="${p.existing?'not-supplied':''} ${isActive(c,'component',p.id,selection,filter,semantics)?'':'muted'}">`+Object.keys(p.terminals).map(key=>{const t=p.terminals[key],colour=p.type==='humbucker'?pickupProfile(c,p.id).wires[key][0]:categoryColours[key==='hot'?'signal':'ground'];return `<path class="pickup-conductor" stroke="${colour}" d="M${p.x+180} ${p.y+118}Q${p.x+185} ${p.y+t.y} ${p.x+t.x} ${p.y+t.y}"/>`;}).join('')+'</g>').join('');
 return `<svg xmlns="http://www.w3.org/2000/svg" id="generator-svg" data-view="${view}" data-presentation="${mode}" viewBox="0 0 1320 1275" role="group" aria-labelledby="generator-title generator-desc"><title id="generator-title">Apparition ${esc(meta)} wiring diagram</title><desc id="generator-desc">Physical component connection diagram. Rear-view pots, lugs down, numbered 3, 2, 1 from left to right. Silver ovals mark ordinary terminations; bronze ovals mark casing solder points; filled dots mark other shared-terminal junctions. Separated crossings do not connect. Pickup wire profiles are shown at each pickup. Toggle and jack terminals are identified by function; verify your hardware.</desc><style>
 text{pointer-events:none;font-family:'JetBrains Mono',monospace;fill:#262626;font-size:14px}.part-title{font-size:15px;font-weight:600;paint-order:stroke;stroke:#f5f5f5;stroke-width:5px;stroke-linejoin:round}.part-value{font-size:14px;paint-order:stroke;stroke:#f5f5f5;stroke-width:4px}.micro{font-size:12px;fill:#666}.terminal-label{font-size:13px;font-weight:bold;paint-order:stroke;stroke:#f5f5f5;stroke-width:4px}[data-view="kit"] .not-supplied{opacity:.24}[data-view="kit"] .supplied .metal{stroke:#927344}.solder-joint{fill:#b9bdba;stroke:#666;stroke-width:1}.casing-solder{fill:#a98755;stroke:#674e2d;stroke-width:1.2}.junction{fill:#63533e}.case-pad{fill:#b5b6b2;stroke:#93958f}.pickup-cable{stroke:#333;stroke-width:10;fill:none;stroke-linecap:round}.coil-label{font-size:10px;fill:#333}.light-label{fill:#ddd}.disc-body{fill:#b68047;stroke:#81552c;stroke-width:2}.film-body{fill:#afac8a;stroke:#73725c;stroke-width:2}.common-lug{stroke:#61491e;stroke-width:3}.metal{fill:#d5d5d2;stroke:#666;stroke-width:2}.rim{fill:none;stroke:#a4a4a0;stroke-width:1}.board{fill:#bc9d67;stroke:#7f6945;stroke-width:2}.pickup-base{fill:#aaa;stroke:#666;stroke-width:2}.bobbin-light{fill:#d2bd93;stroke:#777}.bobbin-dark{fill:#303234;stroke:#111}.screw{fill:#c1c2bd;stroke:#666}.screw-slot{stroke:#333;stroke-width:1.5}.lead{stroke:#858585;stroke-width:3;fill:none}.cap-body{fill:#ca6b32;stroke:#913f19;stroke-width:2}.resistor-body{fill:#d6c19c;stroke:#8b7656;stroke-width:2}.resistor-band{stroke:#775d3f;stroke-width:4}.switch-leaf{stroke:#777;stroke-width:4;fill:none}.jack-hole{fill:#f5f5f5;stroke:#555}.ground-symbol{stroke:#666;stroke-width:3;fill:none}.terminal{fill:transparent;stroke:#735b32;stroke-width:2}.wire-clear{stroke:#f5f5f5;stroke-width:8;fill:none;stroke-linejoin:round}.wire-line{stroke-width:3;fill:none;stroke-linejoin:round}[data-view-state=traced] .wire-line{stroke-width:4.5}[data-view-state=selected] .wire-line{stroke-width:3.8;stroke-dasharray:10 3}.bare-wire{stroke-dasharray:5 3}.wire-hit{stroke:transparent;stroke-width:14;fill:none;cursor:pointer}.insulation{fill:#303234;stroke:#f5f5f5;stroke-width:2}.pickup-conductor{stroke-width:4;fill:none}.muted{opacity:.18}.component,.wire,.terminal{cursor:pointer}.component:focus,.wire:focus{outline:none}.component:focus .metal,.component:focus .pickup-base,.wire:focus .wire-line{stroke:#b91c1c;stroke-width:4}.terminal:focus{stroke:#b91c1c;stroke-width:4;outline:none}.sheet-caption{font-size:12px;fill:#666}.forge-crossing[data-view-state=muted]{opacity:.18}.forge-crossing[data-view-state=selected] path{stroke-dasharray:10 3;stroke-width:3.8}
  [data-presentation="build"] .role-ground{stroke-dasharray:10 4;stroke-width:2.5}[data-presentation="build"] .role-tone{stroke-dasharray:14 2 2 2}[data-presentation="build"] .bare-wire{stroke-dasharray:2 3}[data-presentation="build"] .terminal{stroke-width:2.5}[data-presentation="build"] .unused-terminal{opacity:.4}
 .blade-frame{fill:#d4d4cd;stroke:#6f736c;stroke-width:2}.blade-wafer{fill:#a17c48;stroke:#725831;stroke-width:2}.blade-wafer-seam{fill:none;stroke:#735b3b;stroke-width:2}.blade-lug{fill:#d7d9cc;stroke:#747969;stroke-width:2}.blade-lever{fill:#9fa59d;stroke:#646c62;stroke-width:2}.blade-lever-slot{stroke:#eef0e7;stroke-width:3}.blade-orientation{font-size:10px;fill:#f7f3df}.blade-lug.common-lug{stroke-width:3;stroke:#594724}
 .blade-terminal-label{font-size:11px;fill:#514636;paint-order:stroke;stroke:#f5f5f5;stroke-width:2px}.blade-caption{font-size:10px;fill:#514636}.lug-hole{fill:#f5f5f5;stroke:#777;stroke-width:1}.closed-contact{stroke:#735b32;stroke-width:2;stroke-dasharray:4 3;fill:none}.contact-engaged{stroke-width:3;stroke-dasharray:2 1}.terminal-traced{stroke:#262626;stroke-width:4;fill:#d8bf87}.anchors:has(.terminal:focus){opacity:1}
 </style><rect width="1320" height="1275" fill="#f5f5f5"/>${text(35,28,meta,'part-title','start')}${text(35,49,'REAR VIEW · LUGS DOWN · 1 = CCW END / 2 = WIPER / 3 = CW END','sheet-caption','start')}${bodies}${contacts}${wires}<g pointer-events="none">${crossingMarkers(c,id=>isActive(c,'wire',id,selection,filter,semantics),id=>{const w=c.connections.find(w=>w.id===id),a=endpoint(c,w.from),active=isActive(c,'wire',id,selection,filter,semantics);return {colour:wireColour(w,a),state:active?(selection?.kind==='physical-wire'?'selected':selection?'traced':'active'):'muted'};},{mode:policy.routing})}</g>${conductors}${labelLayer.join('')}${(policy.build?[]:c.components.filter(p=>p.type==='humbucker')).map(p=>{const codes=pickupProfile(c,p.id);return `<g data-pickup-profile="${esc(codes.label)}" class="${isActive(c,'component',p.id,selection,filter,semantics)?'':'muted'}">${text(p.x,p.y-42,codes.label.split(' · ')[0].toUpperCase(),'sheet-caption','start')}${text(p.x,p.y+156,'HOT: '+(codes.status==='generic'?'N START':codes.wires.hot[1]),'sheet-caption','start')}${text(p.x,p.y+174,'JOIN: '+(codes.status==='generic'?'N FIN + S FIN':codes.wires.linkA[1]+' + '+codes.wires.linkB[1]),'sheet-caption','start')}${text(p.x,p.y+192,'GROUND: '+(codes.status==='generic'?'S START':codes.wires.ground[1]),'sheet-caption','start')}${text(p.x,p.y+210,'SHIELD: '+codes.wires.shield[1],'sheet-caption','start')}</g>`;}).join('')}${terminals}${policy.build?text(35,1232,'SOLID: SIGNAL. DASH-DOT: TONE / COMPONENT LEAD. LONG DASH: GROUND. SHORT DASH: SHIELD. HOPS DO NOT JOIN.','sheet-caption','start'):text(35,1210,'BRONZE = CASING SOLDER. SILVER = TERMINATION. DOT = SHARED TERMINAL. SEPARATED CROSSINGS DO NOT JOIN.','sheet-caption','start')+text(35,1232,(view==='kit'?'MUTED: EXISTING / NOT INCLUDED. ':'')+'RED: TONE / GREY: GROUND / DARK: SIGNAL / GOLD: SWITCHING / DASHED LINE / DOUBLE TERMINAL RING: CLOSED SWITCH CONTACT.','sheet-caption','start')+text(35,1254,c.state.guitar==='prs'?'SUPERSWITCH CONVERSION, NOT FACTORY PRS PINOUT. Verify pole identity and pickup coil polarity.':'Generic hardware outline: verify lug functions, viewing orientation and continuity on the actual parts.','sheet-caption','start')}}</svg>`;
}
